const test=require('node:test');
const assert=require('node:assert/strict');
const E=require('./engine.js');
const input=(recipient='M1',tags=['대화가 편안한 사람'],description='')=>({recipient,tags,description,confirmed:true});
function request(){const s=E.submit(E.initial(),input());return {s,id:s.active[0].id};}
test('01: L0 / 0 cards remains, nudge not a proposal',()=>{const s=E.submit(E.initial(),input());assert.equal(s.visibility,'L0');assert.equal(s.cardsAvailable,0);assert.equal(s.events.preference_nudge_submitted,1);assert.equal(s.events.proposal_created,0);assert.equal(s.events.mutually_accepted,0);assert.equal(s.events.introduced,0);});
test('02: M1 gets its message, M2 does not',()=>{const {s}=request();assert.equal(E.inbox(s,'M1').length,1);assert.equal(E.inbox(s,'M2').length,0)});
test('03: M2 is not allowed to review M1',()=>{const {s,id}=request();assert.throws(()=>E.startReview(s,id,'M2'),/수신|열람/)});
test('04: tags required',()=>assert.throws(()=>E.submit(E.initial(),input('M1',[])),/1~3/));
test('05: three tags allowed',()=>assert.equal(E.submit(E.initial(),input('M1',E.KEYWORDS.slice(0,3))).active[0].tags.length,3));
test('06: four tags forbidden',()=>assert.throws(()=>E.submit(E.initial(),input('M1',E.KEYWORDS.slice(0,4))),/1~3/));
test('07: duplicate tags forbidden',()=>assert.throws(()=>E.submit(E.initial(),input('M1',[E.KEYWORDS[0],E.KEYWORDS[0]])),/중복/));
test('08: foreign tags forbidden',()=>assert.throws(()=>E.submit(E.initial(),input('M1',['모르는 표현'])),/허용된/));
test('09: free description optional',()=>assert.equal(E.submit(E.initial(),input()).active[0].description,''));
test('10: 120 codepoints allowed',()=>assert.equal(E.submit(E.initial(),input('M1',[E.KEYWORDS[1]],'가'.repeat(120))).active[0].description.length,120));
test('11: 121 codepoints forbidden',()=>assert.throws(()=>E.submit(E.initial(),input('M1',[E.KEYWORDS[1]],'가'.repeat(121))),/120/));
test('12: recipient/content confirmation required',()=>assert.throws(()=>E.submit(E.initial(),{...input(),confirmed:false}),/확인/));
test('13: active one request per maker',()=>{const {s}=request();assert.throws(()=>E.submit(s,input()),/진행 중/)});
test('14: independent open requests to M1 and M2',()=>{let s=E.submit(E.initial(),input());s=E.submit(s,input('M2',[E.KEYWORDS[1]]));assert.equal(s.active.length,2);assert.equal(E.inbox(s,'M2').length,1)});
test('15: reviewing is not closed and retains original',()=>{const {s,id}=request();const n=E.startReview(s,id,'M1');assert.equal(n.active[0].status,'reviewing');assert.equal(n.active[0].description,'');assert.equal(n.active[0].firstReviewedAt,s.now);});
test('16: first review resets expiry one time',()=>{let {s,id}=request();s=E.advanceTime(s,6*24);s=E.startReview(s,id,'M1');assert.equal(s.active[0].expiresAt,s.now+7*E.DAY);assert.throws(()=>E.startReview(s,id,'M1'),/이미 검토/);});
test('17: before 7 days not expired; at 7 days expires',()=>{let {s}=request();s=E.advanceTime(s,7*24-1/60);assert.equal(s.active.length,1);s=E.advanceTime(s,1/60);assert.equal(s.active.length,0);assert.equal(s.archives.M1[0].status,E.TERMINAL.expired);});
test('18: after review, 7 days count from review start',()=>{let {s,id}=request();s=E.advanceTime(s,6*24);s=E.startReview(s,id,'M1');s=E.advanceTime(s,6*24);assert.equal(s.active.length,1);s=E.advanceTime(s,24);assert.equal(s.active.length,0);});
test('19: user withdrawal removes both tags and description',()=>{let s=E.submit(E.initial(),input('M1',[E.KEYWORDS[0]],'책 읽는 시간을 좋아해요'));s=E.startReview(s,s.active[0].id,'M1');s=E.withdraw(s,s.active[0].id);assert.equal(s.active.length,0);assert.equal(E.inbox(s,'M1').length,0);assert.equal(s.archives.M1.length,1);assert.equal(JSON.stringify(s).includes('책 읽는 시간을'),false);assert.equal(JSON.stringify(s.archives).includes('대화가 편안한 사람'),false);});
test('20: withdrawal during received allowed',()=>{let {s,id}=request();s=E.withdraw(s,id);assert.equal(s.archives.M1[0].status,E.TERMINAL.withdrawn);});
test('21: cooldown after withdrawal blocks earlier than 24h',()=>{let {s,id}=request();s=E.withdraw(s,id);s=E.advanceTime(s,23);assert.throws(()=>E.submit(s,input()),/24시간/);});
test('22: cooldown exactly 24h allows re-request with new ID',()=>{let {s,id}=request();s=E.withdraw(s,id);s=E.advanceTime(s,24);s=E.submit(s,input());assert.equal(s.active.length,1);assert.notEqual(s.active[0].id,id);});
test('23: M2 independent of M1 cooldown',()=>{let {s,id}=request();s=E.withdraw(s,id);s=E.submit(s,input('M2'));assert.equal(s.active.length,1);assert.equal(s.active[0].to,'M2');});
test('24: unlink M1 closes own and preserves M2',()=>{let s=E.submit(E.initial(),input());s=E.submit(s,input('M2'));s=E.unlink(s,'M1');assert.equal(E.inbox(s,'M1').length,0);assert.equal(E.inbox(s,'M2').length,1);assert.equal(s.archives.M1[0].status,E.TERMINAL.unlinked);});
test('25: unlinked recipient cannot receive or read',()=>{let s=E.unlink(E.initial(),'M1');assert.throws(()=>E.submit(s,input()),/연결/);assert.equal(E.inbox(s,'M1').length,0)});
test('26: internal possible_later is invisible as user closure',()=>{let {s,id}=request();s=E.startReview(s,id,'M1');s=E.closeByMatchmaker(s,id,'M1','possible_later');assert.equal(E.displayStatus(s.archives.M1[0].status),'종료');assert.equal(s.archives.M1[0].status,E.TERMINAL.possible);assert.equal(s.events.introduced,0);});
test('27: cannot_proceed displays generic closed to single',()=>{let {s,id}=request();s=E.startReview(s,id,'M1');s=E.closeByMatchmaker(s,id,'M1','cannot_proceed');assert.equal(E.displayStatus(s.archives.M1[0].status),'종료');});
test('28: closure must follow review',()=>{let {s,id}=request();assert.throws(()=>E.closeByMatchmaker(s,id,'M1','possible_later'),/검토를 시작/);});
test('29: closed status distinguishes withdrawal, expiry, unlink',()=>{for(const [code,needle] of [[E.TERMINAL.withdrawn,'철회'],[E.TERMINAL.expired,'만료'],[E.TERMINAL.unlinked,'연결 해제']])assert.ok(E.displayStatus(code).includes(needle));});
test('30: contact, email, link, ID and personal-number patterns rejected',()=>{for(const phrase of ['010-1234-5678','test@example.com','https://example.com','연락처 알려줘','주민등록번호 123456-1234567','카톡 아이디 공유']){assert.equal(E.forbidden(phrase),true);assert.throws(()=>E.submit(E.initial(),input('M1',[E.KEYWORDS[0]],phrase)),/수정/);}});
test('31: no external alerts, automatic messages or real identity stored in engine',()=>{const {s}=request();assert.deepEqual(Object.keys(s.events).sort(),['introduced','mutually_accepted','preference_nudge_submitted','proposal_created']);assert.equal(s.events.introduced,0);});
test('32: archive contains ID timestamps and status only',()=>{let {s,id}=request();s=E.withdraw(s,id);assert.deepEqual(Object.keys(s.archives.M1[0]).sort(),['closedAt','id','status','submittedAt']);});
test('33: no persistence across initial() call',()=>{const {s}=request();assert.equal(s.active.length,1);assert.equal(E.initial().active.length,0);});
